(function(){
 const IMAGE_KEY='zwconnect-owner-shop-images-v2',WORKER_CART_KEY='zwconnect-worker-cart-v2',PURCHASE_KEY='zwconnect-purchases-v2',EXPENSE_KEY='zwconnect-expenses-v2',PERMISSION_KEY='zwconnect-purchasing-permissions-v2';
 let storageScope='signed-out';
 function scoped(key){return`${key}:${storageScope}`}
 let shopImages=load(scoped(IMAGE_KEY),[]),workerCart=load(scoped(WORKER_CART_KEY),[]),purchaseRecords=load(scoped(PURCHASE_KEY),[]),expenseRecords=load(scoped(EXPENSE_KEY),[]),purchasingPermissions=load(scoped(PERMISSION_KEY),{0:{purchase:true,expenses:true}}),ownerSubscription=null,customerTrackingTimer=null,customerTrackingMap=null,customerCourierMarker=null,customerTrackingOrder=null;
 function load(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}}
 function safeText(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
 function persist(){localStorage.setItem(scoped(IMAGE_KEY),JSON.stringify(shopImages.map(({preview,...x})=>x)));localStorage.setItem(scoped(WORKER_CART_KEY),JSON.stringify(workerCart));localStorage.setItem(scoped(PURCHASE_KEY),JSON.stringify(purchaseRecords));localStorage.setItem(scoped(EXPENSE_KEY),JSON.stringify(expenseRecords));localStorage.setItem(scoped(PERMISSION_KEY),JSON.stringify(purchasingPermissions))}
 function switchStorageScope(detail={}){persist();storageScope=`${detail.userId||'signed-out'}:${detail.shopId||'no-shop'}`;shopImages=load(scoped(IMAGE_KEY),[]);workerCart=load(scoped(WORKER_CART_KEY),[]);purchaseRecords=load(scoped(PURCHASE_KEY),[]);expenseRecords=load(scoped(EXPENSE_KEY),[]);purchasingPermissions=load(scoped(PERMISSION_KEY),{0:{purchase:true,expenses:true}});if(state.portalRole&&['sell','purchasing'].includes(state.portalTab))renderPortal()}
 window.addEventListener('zwconnect:identity-change',event=>switchStorageScope(event.detail));
 function ownerShop(){return shops[0]}
 function ownerDbId(){return databaseShopId(ownerShop())}
 function purchasingProducts(){return ownerShop().products}
 function renderPurchasingWorkspace(){const owner=state.portalRole==='owner',allowed=owner||Object.values(purchasingPermissions).some(x=>x.purchase||x.expenses);document.querySelector('#portalContent').innerHTML=`<div class="metric-grid">${metric('package-plus','Purchase batches',purchaseRecords.length)}${metric('layers','FIFO costing','Active')}${metric('receipt','Recorded expenses',expenseRecords.length)}${metric('user-check','Authorisation',owner?'Owner':'Purchasing privilege')}</div>${allowed?`<div class="purchasing-layout"><section class="portal-panel"><div class="panel-head"><div><h2>Receive purchased stock</h2><p>Record every delivery as a separate cost layer. The purchaser may also set the current selling price.</p></div><span class="status-pill approved">FIFO batch</span></div><form id="stockPurchaseForm" class="purchase-form"><label>Product<select name="sku">${purchasingProducts().map(p=>`<option value="${p.sku}">${p.name} • ${p.quantity} in stock</option>`).join('')}</select></label><label>Quantity received<input name="quantity" type="number" min="0.001" step="0.001" required></label><label>Purchase cost per unit<input name="unitCost" type="number" min="0" step="0.01" required></label><label>New selling price<input name="sellingPrice" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Supplier<input name="supplier" required></label><label>Supplier invoice<input name="invoice" required></label><label>Payment source<select name="paymentSource"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_money">Mobile money</option><option value="credit">Supplier credit</option></select></label><label>Purchased at<input name="purchasedAt" type="datetime-local" required></label><label class="wide">Notes<textarea name="notes" placeholder="Batch, delivery or quality notes"></textarea></label><button class="primary-button wide">Record stock purchase</button></form></section><section class="portal-panel"><div class="panel-head"><div><h2>Record purchasing expense</h2><p>Fuel, transport, loading and other procurement costs remain separate from product cost.</p></div></div><form id="purchaseExpenseForm" class="purchase-form"><label>Category<select name="category"><option value="transport">Transport</option><option value="fuel">Fuel</option><option value="loading">Loading / offloading</option><option value="packaging">Packaging</option><option value="communication">Communication</option><option value="other">Other</option></select></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Payment source<select name="paymentSource"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_money">Mobile money</option></select></label><label>Expense date<input name="expenseDate" type="date" required></label><label class="wide">Description<textarea name="description" required></textarea></label><button class="secondary-button wide">Record expense</button></form></section></div><section class="portal-panel"><div class="panel-head"><div><h2>Recent purchase cost layers</h2><p>Later prices never overwrite earlier batches. Sales consume the oldest remaining quantities first.</p></div></div><div class="cost-layer-list">${purchaseRecords.map(x=>`<article><span>${x.emoji||'📦'}</span><div><strong>${safeText(x.product)}</strong><small>${x.quantity} units @ US$ ${Number(x.unitCost).toFixed(2)} • ${safeText(x.supplier)}</small></div><b>US$ ${Number(x.quantity*x.unitCost).toFixed(2)}</b></article>`).join('')||'<div class="permission-note"><strong>FIFO example:</strong> 10 units bought at US$4.00 in the morning and 20 at US$4.50 in the afternoon remain as two separate layers.</div>'}</div></section>`:`<section class="portal-panel"><div class="empty-state"><i data-lucide="shield-alert"></i><h3>Purchasing permission required</h3><p>The shop owner must grant your worker account purchasing or expense privileges.</p></div></section>`}`;window.lucide?.createIcons()}
 function renderPurchasingPermissions(){const host=document.querySelector('#portalContent');if(!host||state.portalRole!=='owner')return;host.insertAdjacentHTML('beforeend',`<section class="portal-panel"><div class="panel-head"><div><h2>Purchasing privileges</h2><p>Grant either permission to one or more regular workers. Their platform role stays worker.</p></div><span class="status-pill approved">Owner controlled</span></div><div class="permission-worker-list">${workers.map((w,index)=>{const p=purchasingPermissions[index]||{};return `<article><div><strong>${safeText(w.name)}</strong><small>${safeText(w.job)} • ${safeText(w.email)}</small></div><label><input type="checkbox" data-purchase-permission="${index}" ${p.purchase?'checked':''}> Record purchases</label><label><input type="checkbox" data-expense-permission="${index}" ${p.expenses?'checked':''}> Record expenses</label></article>`}).join('')}</div></section>`);window.lucide?.createIcons()}
 async function renderProfitAnalysis(){const demo={revenue:1250,cogs:760,gross_profit:490,expenses:85,net_profit:405};const paint=s=>{document.querySelector('#portalContent').innerHTML=`<div class="metric-grid">${metric('circle-dollar-sign','Sales revenue',`US$ ${Number(s.revenue||0).toFixed(2)}`)}${metric('package-minus','FIFO cost of goods',`US$ ${Number(s.cogs||0).toFixed(2)}`)}${metric('trending-up','Gross profit',`US$ ${Number(s.gross_profit||0).toFixed(2)}`)}${metric('badge-dollar-sign','Net after expenses',`US$ ${Number(s.net_profit||0).toFixed(2)}`)}</div><div class="profit-layout"><section class="portal-panel"><div class="panel-head"><div><h2>Profit calculation</h2><p>Revenue minus exact FIFO purchase costs, then minus recorded operating expenses.</p></div><span class="status-pill approved">Owner only</span></div><div class="profit-equation"><span>Revenue<strong>US$ ${Number(s.revenue||0).toFixed(2)}</strong></span><b>−</b><span>COGS<strong>US$ ${Number(s.cogs||0).toFixed(2)}</strong></span><b>=</b><span>Gross profit<strong>US$ ${Number(s.gross_profit||0).toFixed(2)}</strong></span><b>−</b><span>Expenses<strong>US$ ${Number(s.expenses||0).toFixed(2)}</strong></span><b>=</b><span>Net profit<strong>US$ ${Number(s.net_profit||0).toFixed(2)}</strong></span></div></section><section class="portal-panel"><div class="panel-head"><div><h2>Different purchase prices</h2><p>Example of a sale crossing two cost layers.</p></div></div><div class="fifo-example"><div><span>Morning purchase</span><strong>10 × US$4.00</strong><b>US$40.00</b></div><div><span>Afternoon purchase used</span><strong>2 × US$4.50</strong><b>US$9.00</b></div><div class="total"><span>COGS for 12 units</span><strong>FIFO allocation</strong><b>US$49.00</b></div></div></section></div>`;window.lucide?.createIcons()};paint(demo);if(!window.zwconnectSupabase||!navigator.onLine||!ownerDbId())return;const {data}=await window.zwconnectSupabase.rpc('get_shop_profit_summary',{target_shop:ownerDbId(),period_start:null,period_end:null});if(data&&state.portalRole==='owner'&&state.portalTab==='profit')paint(data)}
 function renderImages(){const host=document.querySelector('#ownerShopImages');if(!host)return;const slots=[1,2,3].map(position=>{const image=shopImages.find(x=>x.position===position);return image?`<article class="shop-image-card"><img src="${image.preview||image.publicUrl||ownerShop().image}" alt="${image.alt||ownerShop().name}"><button data-remove-shop-image="${image.id}" aria-label="Remove image"><i data-lucide="trash-2"></i></button></article>`:`<article class="shop-image-card"><div class="empty-image"><span><i data-lucide="image-plus"></i><strong>Image ${position}</strong><small>JPG, PNG or WebP</small></span></div></article>`}).join('');host.innerHTML=slots;window.lucide?.createIcons()}
 function appendOwnerImages(){if(document.querySelector('#ownerImagePanel'))return;const container=document.querySelector('#portalContent');container?.insertAdjacentHTML('beforeend',`<section class="portal-panel owner-image-panel" id="ownerImagePanel"><div class="panel-head"><div><h2>Shop profile images</h2><p>Upload up to three storefront or product-range images. The limit is enforced in Supabase.</p></div><span class="status-pill ${shopImages.length>=3?'':'approved'}">${shopImages.length}/3 images</span></div><form id="shopImageForm" class="shop-image-upload"><input name="image" type="file" accept="image/jpeg,image/png,image/webp" required ${shopImages.length>=3?'disabled':''}><input name="alt" placeholder="Image description" required><button class="primary-button" ${shopImages.length>=3?'disabled':''}>Upload image</button></form><div id="ownerShopImages" class="shop-image-grid"></div></section>`);renderImages()}
 const originalRenderOwner=renderOwner,originalRenderWorker=renderWorker;
 renderOwner=function(tab){if(tab==='subscription'){renderOwnerSubscription();return}if(tab==='purchasing'){renderPurchasingWorkspace();return}if(tab==='profit'){renderProfitAnalysis();return}originalRenderOwner(tab);if(tab==='setup')appendOwnerImages();if(tab==='workers')renderPurchasingPermissions()};
 renderOwnerSubscription=function(){hydrateOwnerSubscription();const sub=ownerSubscription||{amount:25,status:'active',ends_at:'2026-12-18T00:00:00Z',duration_days:30};document.querySelector('#portalContent').innerHTML=`<div class="metric-grid">${metric('badge-check','Subscription status',sub.status)}${metric('circle-dollar-sign','Current amount',`US$ ${Number(sub.amount).toFixed(2)}`)}${metric('calendar-days','Access until',sub.ends_at?new Date(sub.ends_at).toLocaleDateString():'Not set')}${metric('clock-3','Billing cycle',`${sub.duration_days} days`)}</div><section class="portal-panel"><div class="panel-head"><div><h2>Manage your subscription</h2><p>Renew, request an extension, or request cancellation. The site administrator reviews each request.</p></div><span class="status-pill approved">Owner only</span></div><div class="subscription-actions"><button class="primary-button" data-owner-sub-request="renew"><i data-lucide="refresh-cw"></i> Renew subscription</button><button class="secondary-button" data-owner-sub-request="extend"><i data-lucide="calendar-plus"></i> Extend duration</button><button class="secondary-button" data-owner-sub-request="cancel"><i data-lucide="circle-x"></i> Cancel subscription</button></div><div class="permission-note"><strong>Access protection:</strong> cancellation is a request and does not erase shop records. The administrator confirms the effective date.</div></section>`;window.lucide?.createIcons()};
 async function hydrateOwnerSubscription(){if(ownerSubscription||!window.zwconnectSupabase||!navigator.onLine||!ownerDbId())return;const {data}=await window.zwconnectSupabase.from('shop_subscriptions').select('amount,duration_days,trial_ends_at,ends_at,status').eq('shop_id',ownerDbId()).maybeSingle();if(data){ownerSubscription=data;if(state.portalTab==='subscription')renderOwnerSubscription()}}
 function workerProduct(sku){return ownerShop().products.find(p=>p.sku===sku)}
 function lineBase(line){const p=workerProduct(line.sku);return line.quantity*(line.saleUnit==='case'?p.caseSize:1)}
 function linePrice(line){const p=workerProduct(line.sku);return line.saleUnit==='case'?p.casePrice:p.price}
 function cartTotal(){return workerCart.reduce((n,line)=>n+line.quantity*linePrice(line),0)}
 function renderWorkerCart(){const shop=ownerShop();document.querySelector('#portalContent').innerHTML=`<div class="metric-grid">${metric('shopping-cart','Cart lines',workerCart.length)}${metric('package-check','Available products',shop.products.filter(p=>p.quantity>0).length)}${metric('boxes','Case & unit sales',salesModeLabel(shop.salesMode))}${metric('cloud-check','Offline posting','Enabled')}</div><div class="worker-cart-layout"><section class="portal-panel"><div class="panel-head"><div><h2>Build customer cart</h2><p>Add multiple products before taking payment.</p></div></div><div class="worker-product-list">${shop.products.filter(p=>p.quantity>0).map(p=>`<article class="worker-product"><div><strong>${p.name}</strong><small>${p.sku} • ${p.quantity} units available</small></div><button data-worker-add="${p.sku}">Add</button></article>`).join('')}</div></section><section class="portal-panel"><div class="panel-head"><div><h2>Current customer order</h2><p>Stock is validated in singular base units at checkout.</p></div><button data-worker-clear>Clear</button></div><div class="worker-cart-lines">${workerCart.map((line,index)=>{const p=workerProduct(line.sku);return `<article class="worker-cart-line"><div><strong>${line.quantity} ${line.saleUnit}${line.quantity===1?'':'s'} • ${p.name}</strong><small>${lineBase(line)} base units • US$ ${(linePrice(line)*line.quantity).toFixed(2)}</small></div><button data-worker-remove="${index}">Remove</button></article>`}).join('')||'<div class="empty-state"><i data-lucide="shopping-cart"></i><p>Add products for this customer.</p></div>'}</div><div class="worker-cart-total"><span>Total</span><strong>US$ ${cartTotal().toFixed(2)}</strong></div><form id="workerCartCheckout" class="worker-checkout-form"><label>Customer name<input name="customer" required></label><label>Payment<select name="payment"><option value="cash">Cash</option><option value="ecocash">EcoCash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option></select></label><button class="primary-button" ${workerCart.length?'':'disabled'}>Complete multi-item sale</button></form></section></div>`;window.lucide?.createIcons()}
 renderWorker=function(tab){if(tab==='sell'){renderWorkerCart();return}if(tab==='purchasing'){renderPurchasingWorkspace();return}originalRenderWorker(tab)};
 async function submitWorkerCart(form){if(!workerCart.length)return;for(const line of workerCart){const p=workerProduct(line.sku);if(!p||lineBase(line)>p.quantity)return showToast(`Insufficient stock for ${p?.name||line.sku}`,'triangle-alert')}const d=Object.fromEntries(new FormData(form)),items=workerCart.map(line=>({sku:line.sku,quantity:line.quantity,sale_unit:line.saleUnit,units_per_case:line.saleUnit==='case'?workerProduct(line.sku).caseSize:1,base_quantity:lineBase(line),unit_price:linePrice(line)})),total=Number(cartTotal().toFixed(2)),deviceId=localStorage.getItem('zwconnect-device-id')||crypto.randomUUID();localStorage.setItem('zwconnect-device-id',deviceId);items.forEach(item=>applyLocalMovement(ownerShop().id,item.sku,-item.base_quantity));await window.ZWOffline.enqueue('sale.create',{shopId:ownerDbId(),localShopId:ownerShop().id,items,paymentMethod:d.payment,total,soldAt:new Date().toISOString(),deviceId,customerName:d.customer},{role:'worker'});workerCart=[];persist();showToast(`Multi-item sale completed • US$ ${total.toFixed(2)}`,'receipt-text');renderWorkerCart()}
 async function hydrateShopImages(){if(!window.zwconnectSupabase||!navigator.onLine||!ownerDbId())return;const {data}=await window.zwconnectSupabase.from('shop_images').select('id,public_url,storage_path,alt_text,position').eq('shop_id',ownerDbId()).order('position');if(data){shopImages=data.map(x=>({id:x.id,position:x.position,publicUrl:x.public_url||window.zwconnectSupabase.storage.from('shop-images').getPublicUrl(x.storage_path).data.publicUrl,alt:safeText(x.alt_text),path:x.storage_path}));persist();renderImages()}}
 async function hydrateOwnerContext(){if(!window.zwconnectSupabase||!navigator.onLine)return;const {data:userData}=await window.zwconnectSupabase.auth.getUser(),user=userData?.user;if(!user)return;const {data:shopRow}=await window.zwconnectSupabase.from('shops').select('id,name').eq('owner_id',user.id).is('deleted_at',null).order('created_at').limit(1).maybeSingle();if(shopRow){let ids={};try{ids=JSON.parse(localStorage.getItem('zwconnect-shop-database-ids')||'{}')}catch{}ids[ownerShop().name]=shopRow.id;ids[shopRow.name]=shopRow.id;localStorage.setItem('zwconnect-shop-database-ids',JSON.stringify(ids));await window.ZWOffline?.setContext(state.portalRole==='worker'?'worker':'shop_owner',{userId:user.id,email:user.email||null,shopId:shopRow.id,force:true});hydrateShopImages();hydrateOwnerSubscription()}}
 async function hydrateBusinessProfiles(){if(!window.zwconnectSupabase||!navigator.onLine)return;const {data,error}=await window.zwconnectSupabase.from('business_profiles').select('id,title,icon,description,display_order,enabled').eq('enabled',true).order('display_order');if(error||!data?.length)return;const existing=new Map(profiles.map(p=>[p.id,p]));profiles.splice(0,profiles.length,...data.map((row,index)=>({...existing.get(row.id),id:row.id,title:row.title,icon:row.icon,desc:row.description,tools:existing.get(row.id)?.tools||[],color:existing.get(row.id)?.color||['#e4f4ed','#eaf0ff','#fff0e4'][index%3],ink:existing.get(row.id)?.ink||'#075f4b',image:existing.get(row.id)?.image||'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=900&q=80'})));if(!document.querySelector('#homePage').classList.contains('hidden'))renderProfiles()}
 async function renderPublicShopGallery(){const detail=document.querySelector('#shopDetail'),shop=state.shop;if(!detail||!shop||detail.querySelector('.shop-gallery-strip'))return;let images=shop.id===ownerShop().id?shopImages:[],shopId=databaseShopId(shop);if(window.zwconnectSupabase&&navigator.onLine&&shopId){const {data}=await window.zwconnectSupabase.from('shop_images').select('storage_path,public_url,alt_text,position').eq('shop_id',shopId).order('position');if(data)images=data.map(x=>({publicUrl:x.public_url||window.zwconnectSupabase.storage.from('shop-images').getPublicUrl(x.storage_path).data.publicUrl,alt:safeText(x.alt_text)}))}if(images.length){const hero=detail.querySelector('.shop-hero');hero?.insertAdjacentHTML('afterend',`<div class="shop-gallery-strip">${images.slice(0,3).map(x=>`<img src="${x.preview||x.publicUrl}" alt="${x.alt||safeText(shop.name)}">`).join('')}</div>`)}}
 function injectSupport(){const nav=document.querySelector('.header-actions');if(nav&&!document.querySelector('#supportButton'))nav.insertAdjacentHTML('afterbegin','<button class="text-button support-launch" id="supportButton"><i data-lucide="life-buoy"></i><span>Support</span></button>');document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="supportModal" aria-hidden="true"><section class="modal support-modal" role="dialog" aria-modal="true"><button class="modal-close" data-close="supportModal"><i data-lucide="x"></i></button><p class="kicker">ZWCONNECT SUPPORT</p><h2>Send a request or complaint</h2><form id="supportTicketForm"><label>Name<input name="name" required></label><label>Email<input name="email" type="email"></label><label>Phone<input name="phone"></label><label>Category<select name="category"><option value="request">Request</option><option value="complaint">Complaint</option><option value="billing">Billing</option><option value="shop">Shop</option><option value="courier">Courier</option><option value="technical">Technical</option><option value="other">Other</option></select></label><label class="wide">Subject<input name="subject" minlength="3" maxlength="160" required></label><label class="wide">Details<textarea name="message" minlength="5" maxlength="5000" required></textarea></label><button class="primary-button wide">Send to support hub</button></form></section></div>`);window.lucide?.createIcons()}
 function trackingAge(recordedAt){if(!recordedAt)return null;return Math.max(0,Math.round((Date.now()-new Date(recordedAt).getTime())/1000))}
 function renderCustomerTracking(data){const host=document.querySelector('#orderTrackerContent');if(!host||!data)return;let panel=host.querySelector('#customerCourierTracking');if(!panel){host.insertAdjacentHTML('beforeend','<section class="tracker-action customer-courier-tracking" id="customerCourierTracking"><div class="tracking-panel-head"><div><small>LIVE COURIER LOCATION</small><h3 id="trackingCourierName">Selected courier</h3></div><span class="live-location-badge"><i data-lucide="radio"></i> Live</span></div><div class="customer-tracking-map" id="customerTrackingMap"></div><div class="tracking-metrics" id="customerTrackingMetrics"></div><p class="tracking-privacy"><i data-lucide="shield-check"></i> This location is visible only through your private order tracking code.</p></section>');panel=host.querySelector('#customerCourierTracking')}const age=trackingAge(data.recorded_at),stale=age===null||age>60,prePickup=data.status==='accepted',eta=prePickup?data.pickup_eta_minutes:data.delivery_eta_minutes,distance=prePickup?data.courier_to_pickup_km:data.pickup_to_dropoff_km;panel.querySelector('#trackingCourierName').textContent=data.courier||'Selected courier';panel.querySelector('.live-location-badge').classList.toggle('stale',stale);panel.querySelector('.live-location-badge').innerHTML=`<i data-lucide="${stale?'signal-zero':'radio'}"></i> ${stale?'Waiting for update':'Live'}`;panel.querySelector('#customerTrackingMetrics').innerHTML=`<article><small>${prePickup?'TO COLLECTION':'TO CUSTOMER'}</small><strong>${distance==null?'—':`${Number(distance).toFixed(1)} km`}</strong></article><article><small>ESTIMATED TIME</small><strong>${eta?`About ${eta} min`:'Calculating…'}</strong></article><article><small>LAST LOCATION</small><strong>${age===null?'Waiting for courier':age<60?`${age}s ago`:`${Math.floor(age/60)} min ago`}</strong></article>`;const mapNode=panel.querySelector('#customerTrackingMap');if(window.L&&data.pickup_latitude!=null&&data.delivery_latitude!=null){if(!customerTrackingMap||!customerTrackingMap._container?.isConnected){try{customerTrackingMap?.remove()}catch{}customerTrackingMap=L.map(mapNode,{zoomControl:true}).setView([data.pickup_latitude,data.pickup_longitude],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(customerTrackingMap);L.marker([data.pickup_latitude,data.pickup_longitude]).addTo(customerTrackingMap).bindPopup('Collection point');L.marker([data.delivery_latitude,data.delivery_longitude]).addTo(customerTrackingMap).bindPopup('Customer drop-off');customerCourierMarker=null}if(data.latitude!=null){if(!customerCourierMarker)customerCourierMarker=L.marker([data.latitude,data.longitude]).addTo(customerTrackingMap).bindPopup(safeText(data.courier||'Courier'));else customerCourierMarker.setLatLng([data.latitude,data.longitude]);customerTrackingMap.fitBounds([[data.latitude,data.longitude],[prePickup?data.pickup_latitude:data.delivery_latitude,prePickup?data.pickup_longitude:data.delivery_longitude]],{padding:[35,35],maxZoom:16})}setTimeout(()=>customerTrackingMap?.invalidateSize(),50)}window.lucide?.createIcons()}
 async function refreshCustomerTracking(orderId,token){if(!window.zwconnectSupabase||!navigator.onLine)return;const {data,error}=await window.zwconnectSupabase.rpc('get_customer_delivery_tracking',{order_uuid:orderId,tracking_uuid:token});if(!error&&data)renderCustomerTracking(data)}
 function startCustomerTracking(orderId,token){if(customerTrackingOrder!==orderId){clearInterval(customerTrackingTimer);try{customerTrackingMap?.remove()}catch{}customerTrackingMap=null;customerCourierMarker=null;customerTrackingOrder=orderId}refreshCustomerTracking(orderId,token);clearInterval(customerTrackingTimer);customerTrackingTimer=setInterval(()=>refreshCustomerTracking(orderId,token),12000)}
 async function enhanceCustomerReceipt(){if(!window.zwconnectSupabase||!navigator.onLine)return;const form=document.querySelector('#orderLookupForm'),orderId=form?.orderId?.value,token=form?.token?.value;if(!orderId||!token)return;const {data}=await window.zwconnectSupabase.rpc('get_customer_order',{order_uuid:orderId,tracking_uuid:token});if(data?.delivery&&['accepted','collected','courier_completed'].includes(data.delivery.status))startCustomerTracking(orderId,token);if(data?.delivery?.status==='courier_completed'){const host=document.querySelector('#orderTrackerContent');if(host&&!host.querySelector('[data-confirm-delivery-received]'))host.insertAdjacentHTML('beforeend','<section class="tracker-action"><h3>Confirm delivery received</h3><p>The courier marked this delivery complete. Check the parcel, then confirm receipt to close the job.</p><button class="primary-button" data-confirm-delivery-received>Yes, I received the delivery</button></section>');window.lucide?.createIcons()}}
 document.addEventListener('DOMContentLoaded',()=>{const workerNav=portalConfigs.worker.nav.find(n=>n[0]==='sell');if(workerNav)workerNav[2]='Customer cart';injectSupport();hydrateOwnerContext();hydrateShopImages();hydrateBusinessProfiles();new MutationObserver(renderPublicShopGallery).observe(document.querySelector('#shopDetail'),{childList:true,subtree:true})});
 document.addEventListener('click',async e=>{if(e.target.closest('[data-accept-bid]'))setTimeout(enhanceCustomerReceipt,1200);if(e.target.closest('[data-close="orderTrackerModal"]')){clearInterval(customerTrackingTimer);try{customerTrackingMap?.remove()}catch{}customerTrackingMap=null;customerCourierMarker=null;customerTrackingOrder=null}if(e.target.closest('#supportButton'))openModal('supportModal');if(e.target.closest('[data-confirm-delivery-received]')){const form=document.querySelector('#orderLookupForm'),orderId=form.orderId.value,trackingToken=form.token.value;if(confirm('Confirm that the parcel was received in good order?')){await window.ZWOffline.enqueue('delivery.received',{orderId,trackingToken},{role:'public'});e.target.closest('.tracker-action').innerHTML='<h3>Receipt confirmed</h3><p>This delivery is now complete. Thank you.</p>';showToast('Delivery receipt confirmed','package-check')}}const add=e.target.closest('[data-worker-add]');if(add){const p=workerProduct(add.dataset.workerAdd),mode=ownerShop().salesMode==='wholesale'?'case':ownerShop().salesMode==='retail'?'unit':prompt('Sell as unit or case?','unit');if(!['unit','case'].includes(mode))return;if(mode==='case'&&(!p.allowCase||p.caseSize<=1))return showToast('Case sales are not enabled for this product','package-x');const max=Math.floor(p.quantity/(mode==='case'?p.caseSize:1)),line=workerCart.find(x=>x.sku===p.sku&&x.saleUnit===mode),remaining=max-(line?.quantity||0),qty=Number(prompt(`Quantity (maximum ${remaining})`,'1'));if(!Number.isFinite(qty)||qty<1||qty>remaining)return showToast('Enter a quantity within live stock','triangle-alert');if(line)line.quantity+=qty;else workerCart.push({sku:p.sku,saleUnit:mode,quantity:qty});persist();renderWorkerCart()}const remove=e.target.closest('[data-worker-remove]');if(remove){workerCart.splice(Number(remove.dataset.workerRemove),1);persist();renderWorkerCart()}if(e.target.closest('[data-worker-clear]')){workerCart=[];persist();renderWorkerCart()}const sub=e.target.closest('[data-owner-sub-request]');if(sub){const type=sub.dataset.ownerSubRequest,days=type==='extend'?Number(prompt('How many additional days?','30')):null,note=prompt('Add a note for the site administrator',type==='cancel'?'Please cancel at the end of the current paid period.':'Please process this subscription request.');if(note&&(!days||days>0)){window.ZWOffline.enqueue('subscription_request.submit',{shopId:ownerDbId(),type,days,note},{role:'shop_owner'});showToast('Subscription request sent to the admin support hub','calendar-check')}}const imageRemove=e.target.closest('[data-remove-shop-image]');if(imageRemove){const image=shopImages.find(x=>String(x.id)===imageRemove.dataset.removeShopImage);if(image&&confirm('Remove this shop profile image?')){shopImages=shopImages.filter(x=>x!==image);persist();window.ZWOffline.enqueue('shop_image.delete',{imageId:image.id,path:image.path},{role:'shop_owner'});appendOwnerImages();renderImages()}}});
 document.addEventListener('submit',async e=>{if(e.target.id==='orderLookupForm')setTimeout(enhanceCustomerReceipt,700);if(e.target.id==='workerCartCheckout'){e.preventDefault();submitWorkerCart(e.target)}if(e.target.id==='shopImageForm'){e.preventDefault();if(shopImages.length>=3)return showToast('A shop may have no more than 3 profile images','image-off');const d=new FormData(e.target),file=d.get('image');if(!(file instanceof File)||!file.size)return;if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))return showToast('Use a JPG, PNG or WebP image up to 5 MB','file-warning');const position=[1,2,3].find(n=>!shopImages.some(x=>x.position===n)),id=crypto.randomUUID(),rawAlt=String(d.get('alt')||''),record={id,position,alt:safeText(rawAlt),preview:URL.createObjectURL(file),path:null};shopImages.push(record);persist();await window.ZWOffline.enqueue('shop_image.add',{shopId:ownerDbId(),imageId:id,position,alt:rawAlt,file},{id,role:'shop_owner'});renderImages();showToast('Shop image saved and queued for upload','image-plus')}if(e.target.id==='supportTicketForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),role=state.portalRole==='owner'?'shop_owner':state.portalRole==='worker'?'worker':'public';await window.ZWOffline.enqueue('support.submit',{...d,role},{role});closeModal('supportModal');e.target.reset();showToast('Support ticket sent to the moderation centre','life-buoy')}});
 document.addEventListener('change',e=>{const purchase=e.target.closest('[data-purchase-permission]'),expense=e.target.closest('[data-expense-permission]');if(!purchase&&!expense)return;const index=Number((purchase||expense).dataset[purchase?'purchasePermission':'expensePermission']),current=purchasingPermissions[index]||{};if(purchase)current.purchase=purchase.checked;if(expense)current.expenses=expense.checked;purchasingPermissions[index]=current;persist();const worker=workers[index];window.ZWOffline.enqueue('purchasing_permission.set',{shopId:ownerDbId(),workerUserId:worker.userId||null,workerEmail:worker.email,canPurchase:!!current.purchase,canRecordExpenses:!!current.expenses},{role:'shop_owner'});showToast(`Purchasing privileges updated for ${worker.name}`,'user-check')});
 document.addEventListener('submit',async e=>{if(e.target.id==='stockPurchaseForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),product=purchasingProducts().find(p=>p.sku===d.sku),quantity=Number(d.quantity),unitCost=Number(d.unitCost),sellingPrice=d.sellingPrice===''?null:Number(d.sellingPrice),id=crypto.randomUUID();if(!product||quantity<=0||unitCost<0)return showToast('Enter valid purchase quantities and costs','triangle-alert');product.quantity+=quantity;if(sellingPrice!==null)product.price=sellingPrice;purchaseRecords.unshift({id,sku:d.sku,product:product.name,quantity,unitCost,supplier:d.supplier,invoice:d.invoice,purchasedAt:d.purchasedAt});persist();await window.ZWOffline.enqueue('stock_purchase.record',{shopId:ownerDbId(),supplier:d.supplier,invoice:d.invoice,paymentSource:d.paymentSource,purchasedAt:new Date(d.purchasedAt).toISOString(),notes:d.notes||'',items:[{sku:d.sku,quantity,unit_cost:unitCost,selling_price:sellingPrice}]},{id,role:state.portalRole==='owner'?'shop_owner':'worker'});showToast('Purchase batch saved as a new FIFO cost layer','layers');renderPurchasingWorkspace()}if(e.target.id==='purchaseExpenseForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),amount=Number(d.amount),id=crypto.randomUUID();if(amount<=0)return;purchaseRecords=purchaseRecords;await window.ZWOffline.enqueue('purchase_expense.record',{shopId:ownerDbId(),category:d.category,amount,description:d.description,paymentSource:d.paymentSource,expenseDate:d.expenseDate},{id,role:state.portalRole==='owner'?'shop_owner':'worker'});persist();showToast('Purchasing expense recorded with your identity','receipt');e.target.reset()}});
 document.addEventListener('submit',e=>{if(e.target.id==='purchaseExpenseForm'){const d=Object.fromEntries(new FormData(e.target)),amount=Number(d.amount);if(amount>0){expenseRecords.unshift({id:crypto.randomUUID(),category:d.category,amount,description:d.description,paymentSource:d.paymentSource,expenseDate:d.expenseDate});persist()}}});
})();
